const s = $input.first().json;
const p = s.pipeline || {};
const a = s.auto_apply || {};
return [{
  json: {
    etape: 'STATUT',
    done: s.done,
    status: s.status,
    scrapees_brutes: p.raw_count ?? 0,
    prefiltrees: p.prefilter_count ?? 0,
    qualifiees: p.qualified_count ?? 0,
    nouvelles: p.new_count ?? 0,
    doublons_retires: p.duplicates_removed ?? 0,
    mails_envoyes: a.sent ?? 0,
    mails_erreurs: a.errors ?? 0,
    eligibles: a.eligible ?? 0,
    pipeline_progress: p.progress || '',
    apply_progress: a.progress || '',
  }
}];

const d = $input.first().json;
const jobs = d.jobs || [];
if (!jobs.length) {
  return [{ json: {
    etape: 'OFFRES',
    message: 'Aucune offre qualifiée',
    total: 0,
  }}];
}
return jobs.map((j, i) => ({
  json: {
    etape: 'OFFRE',
    n: i + 1,
    total: jobs.length,
    match_score: j.match_score,
    title: j.title,
    company: j.company,
    location: j.location,
    rh_email: j.rh_email,
    rh_source: j.rh_source,
    confidence: j.confidence,
    job_url: j.job_url,
    date_posted: j.date_posted || '',
    doublons_retires_pipeline: d.duplicates_removed ?? 0,
    nouvelles: d.new_count ?? 0,
  }
}));

const d = $input.first().json;
return [{
  json: {
    etape: 'EXCEL',
    ok: !!d.ok,
    nb_offres: d.count,
    fichier_xlsx: d.xlsx,
    fichier_csv: d.csv,
    fichier_json: d.json,
    message: `Excel sauvegardé: ${d.count} offres → ${d.xlsx}`,
  }
}];

const d = $input.first().json;
const bounced = d.bounced || d.results || d.notified || [];
const list = Array.isArray(bounced) ? bounced : [];
const summary = [{
  json: {
    etape: 'BOUNCES_RESUME',
    scanned: d.scanned ?? d.checked ?? null,
    new_bounces: d.new_bounces ?? list.length,
    notified_telegram: d.notified_count ?? d.telegram ?? null,
    message: d.message || 'Scan bounces terminé',
    raw_keys: Object.keys(d),
  }
}];
if (!list.length) return summary;
const rows = list.map((b, i) => ({
  json: {
    etape: 'BOUNCE',
    n: i + 1,
    title: b.title || b.job_title || '',
    company: b.company || '',
    rh_email: b.rh_email || b.email || '',
    job_url: b.job_url || b.url || '',
    status: b.status || 'bounced',
  }
}));
return summary.concat(rows);

const d = $input.first().json;
return [{
  json: {
    etape: 'RAPPORT_MAILS',
    ok: d.ok,
    total: d.total,
    sent: d.sent,
    bounced: d.bounced,
    error: d.error,
    excel_apps: d.xlsx,
    message: d.ok
      ? `✅ Tous OK — ${d.sent} mails envoyés/reçus`
      : `⚠️ ${d.bounced} bounce(s) + ${d.error} erreur(s) sur ${d.total}`,
  }
}];

const d = $('6. Rapport candidatures').first().json;
const apps = d.sent_apps || [];
if (!apps.length) {
  return [{ json: { etape: 'MAIL_ENVOYE', message: 'Aucun mail sent', total: 0 } }];
}
return apps.map((a, i) => ({
  json: {
    etape: 'MAIL_ENVOYE',
    n: i + 1,
    total: apps.length,
    status: a.status,
    title: a.title,
    company: a.company,
    rh_email: a.rh_email,
    match_score: a.match_score,
    job_url: a.job_url,
    sent_at: a.sent_at || '',
  }
}));

const d = $('6. Rapport candidatures').first().json;
const failed = d.failed_for_telegram || [];
const bounced = d.bounced_apps || [];
const errors = d.error_apps || [];
const all = failed.length ? failed : [...bounced, ...errors];
if (!all.length) {
  return [{ json: {
    etape: 'ECHEC',
    message: 'Aucun échec — rien à envoyer sur Telegram',
    total: 0,
    has_failures: false,
  }}];
}
return all.map((a, i) => ({
  json: {
    etape: 'ECHEC',
    n: i + 1,
    total: all.length,
    has_failures: true,
    status: a.status,
    title: a.title,
    company: a.company,
    rh_email: a.rh_email,
    job_url: a.job_url,
  }
}));

const d = $('6. Rapport candidatures').first().json;
return [{ json: {
  etape: 'FIN_OK',
  message: `✅ Terminé — ${d.sent} mails OK, 0 échec`,
  sent: d.sent,
  bounced: d.bounced,
  error: d.error,
}}];

const d = $input.first().json;
const failed = d.failed || [];
const head = [{
  json: {
    etape: 'TELEGRAM',
    ok: d.ok,
    notified: d.notified,
    message: d.message || `${d.notified || 0} job(s) envoyés sur Telegram`,
  }
}];
if (!failed.length) return head;
return head.concat(failed.map((a, i) => ({
  json: {
    etape: 'TELEGRAM_JOB',
    n: i + 1,
    title: a.title,
    company: a.company,
    rh_email: a.rh_email,
    job_url: a.job_url,
    status: a.status,
  }
})));

const d = $input.first().json;
const failed = d.failed_for_telegram || [];
return [{
  json: {
    etape: 'HORAIRE',
    ok: d.ok,
    sent: d.sent,
    bounced: d.bounced,
    error: d.error,
    has_failures: failed.length > 0,
    failed_count: failed.length,
  }
}].concat(failed.map((a, i) => ({
  json: {
    etape: 'HORAIRE_ECHEC',
    n: i + 1,
    title: a.title,
    company: a.company,
    rh_email: a.rh_email,
    job_url: a.job_url,
  }
})));
